arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_0341d60563014eb691b1f92cfd59db64.Models
@using sv_0341d60563014eb691b1f92cfd59db64.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1 class="mb-4">Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success text-center py-5">
        <h2>🎉 Application Submitted!</h2>
        <p class="lead mt-3">Your application has been received.</p>
        <p><strong>Application ID: @_applicationId</strong></p>
    </div>
}
else
{
    <!-- Step Indicator Bar -->
    <nav class="mb-4">
        <ol class="step-indicator d-flex list-unstyled justify-content-between p-0 position-relative">
            @for (int i = 0; i < _stepLabels.Length; i++)
            {
                var stepIndex = i;
                var isCompleted = stepIndex < _currentStep;
                var isCurrent = stepIndex == _currentStep;
                var isFuture = stepIndex > _currentStep;

                <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                    @onclick="() => GoToStep(stepIndex)"
                    style="cursor: @(isCompleted ? "pointer" : "default")">
                    <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center
                                rounded-circle @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")"
                         style="width:36px;height:36px;font-size:0.85rem;">
