{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_0341d60563014eb691b1f92cfd59db64.Models
@using sv_0341d60563014eb691b1f92cfd59db64.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1 class="mb-4">Job Application</h1>

@if (_submitted)
{
    <div class="alert alert-success text-center py-5">
        <h2>🎉 Application Submitted!</h2>
        <p class="lead mt-3">Your application has been received.</p>
        <p><strong>Application ID: @_applicationId</strong></p>
    </div>
}
else
{
    <!-- Step Indicator Bar -->
    <nav class="mb-4">
        <ol class="step-indicator d-flex list-unstyled justify-content-between p-0 position-relative">
            @for (int i = 0; i < _stepLabels.Length; i++)
            {
                var stepIndex = i;
                var isCompleted = stepIndex < _currentStep;
                var isCurrent = stepIndex == _currentStep;
                var isFuture = stepIndex > _currentStep;

                <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                    @onclick="() => GoToStep(stepIndex)"
                    style="cursor: @(isCompleted ? "pointer" : "default")">
                    <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center
                                rounded-circle @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")"
                         style="width:36px;height:36px;font-size:0.85rem;">
                        @if (isCompleted)
                        {
                            <span>✓</span>
                        }
                        else
                        {
                            <span>@(stepIndex + 1)</span>
                        }
                    </div>
                    <small class="@(isFuture ? "text-muted" : "")">@_stepLabels[stepIndex]</small>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
    @if (_currentStep == 0)
    {
        <div class="card">
            <div class="card-header"><h4 class="mb-0">Personal Information</h4></div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="_fullName" placeholder="Enter your full name" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="_email" placeholder="you@example.com" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Address <span class="text-danger">*</span></label>
                    <textarea class="form-control" @bind="_address" rows="2" placeholder="Your mailing address"></textarea>
                </div>
                <div class="d-flex justify-content-end">
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidating">
                        @if (_isValidating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                        Next
                    </button>
                </div>
            </div>
        </div>
    }

    <!-- Step 2: Work History -->
    @if (_currentStep == 1)
    {
        <div class="card">
            <div class="card-header"><h4 class="mb-0">Work History</h4></div>
            <div class="card-body">
                @for (int i = 0; i < _workEntries.Count; i++)
                {
                    var idx = i;
                    <div class="border rounded p-3 mb-3 position-relative">
                        <h5>Position @(idx + 1)</h5>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn btn-sm btn-outline-danger position-absolute" style="top:10px;right:10px"
                                    @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                        }
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                                <input class="form-control" @bind="_workEntries[idx].Company" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" @bind="_workEntries[idx].Title" />
                            </div>
                        </div>
                        <div class="row">
                            <div class="col-md-4 mb-3">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" @bind="_workEntries[idx].StartDate" />
                            </div>
                            <div class="col-md-4 mb-3">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" @bind="_workEntries[idx].EndDate"
                                       disabled="@_workEntries[idx].IsCurrent" />
                            </div>
                            <div class="col-md-4 mb-3 d-flex align-items-end">
                                <div class="form-check">
                                    <input type="checkbox" class="form-check-input" id="current-@idx"
                                           @bind="_workEntries[idx].IsCurrent" />
                                    <label class="form-check-label" for="current-@idx">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" @bind="_workEntries[idx].Description" rows="2"></textarea>
                        </div>
                    </div>
                }
                <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">
                    + Add Another Position
                </button>
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        </div>
    }

    <!-- Step 3: References -->
    @if (_currentStep == 2)
    {
        <div class="card">
            <div class="card-header"><h4 class="mb-0">References</h4></div>
            <div class="card-body">
                @for (int i = 0; i < _references.Count; i++)
                {
                    var idx = i;
                    <div class="border rounded p-3 mb-3 position-relative">
                        <h5>Reference @(idx + 1)</h5>
                        @if (_references.Count > 2)
                        {
                            <button class="btn btn-sm btn-outline-danger position-absolute" style="top:10px;right:10px"
                                    @onclick="() => RemoveReference(idx)">Remove</button>
                        }
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" @bind="_references[idx].Name" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" @bind="_references[idx].Relationship" placeholder="e.g. Former Manager" />
                            </div>
                        </div>
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" @bind="_references[idx].Email" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" @bind="_references[idx].Phone" />
                            </div>
                        </div>
                    </div>
                }
                @if (_references.Count < 3)
                {
                    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                        + Add Reference
                    </button>
                }
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        </div>
    }

    <!-- Step 4: Cover Letter -->
    @if (_currentStep == 3)
    {
        <div class="card">
            <div class="card-header"><h4 class="mb-0">Cover Letter</h4></div>
            <div class="card-body">
                <div class="mb-2">
                    <textarea class="form-control" @bind="_coverLetter" @bind:event="oninput" rows="12"
                              placeholder="Write your cover letter here..." maxlength="2000"></textarea>
                </div>
                <div class="text-muted text-end mb-3">
                    @(_coverLetter?.Length ?? 0) / 2000 characters
                </div>
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (_currentStep == 4)
    {
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h4 class="mb-0">Personal Information</h4>
                <button class="btn btn-sm btn-link" @onclick="() => GoToStep(0)">Edit</button>
            </div>
            <div class="card-body">
                <dl class="row mb-0">
                    <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                </dl>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h4 class="mb-0">Work History</h4>
                <button class="btn btn-sm btn-link" @onclick="() => GoToStep(1)">Edit</button>
            </div>
            <div class="card-body">
                @foreach (var entry in _workEntries)
                {
                    <div class="mb-3 pb-3 border-bottom">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h4 class="mb-0">References</h4>
                <button class="btn btn-sm btn-link" @onclick="() => GoToStep(2)">Edit</button>
            </div>
            <div class="card-body">
                @foreach (var r in _references)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> — @r.Relationship<br />
                        <small>@r.Email · @r.Phone</small>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h4 class="mb-0">Cover Letter</h4>
                <button class="btn btn-sm btn-link" @onclick="() => GoToStep(3)">Edit</button>
            </div>
            <div class="card-body">
                <p style="white-space:pre-wrap;">@_coverLetter</p>
            </div>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                @if (_isSubmitting) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Submit Application
            </button>
        </div>
    }
}

